const body = $json.body || $json;
const entry = (body.entry || [])[0] || {};
const change = ((entry.changes || [])[0] || {}).value || {};
const msg = ((change.messages || [])[0]) || {};
const text = String((msg.text || {}).body || msg.button?.text || '').trim().toLowerCase();
const from = msg.from || '';
const faqs = {
  horario: 'Atendemos lun–vie 9 a 18 hs.',
  precio: 'Te paso la lista de precios por este chat en un momento.',
  direccion: 'Estamos en el centro — te mando el mapa si querés.',
};
let intent = 'handoff';
let reply = 'Te derivo con una persona del equipo.';
for (const [k, v] of Object.entries(faqs)) {
  if (text.includes(k) || text.includes(k.replace('cion','ción'))) {
    intent = 'faq';
    reply = v;
    break;
  }
}
if (!text) {
  intent = 'ignore';
  reply = '';
}
return [{ json: { ok: true, from, text, intent, reply, todo: 'TODO_CREDENCIAL: enviar reply vía Meta Graph API' } }];
